"""Legacy-compatible numeric division semantics."""

from typing import Any


def _coerce_number(value: Any) -> float:
    """Apply legacy numeric coercion."""
    if value is None:
        return 0.0
    if isinstance(value, str) and value.strip() == "":
        return 0.0
    return float(value)


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using Meridian CRM's legacy division-by-zero behavior."""
    numerator = _coerce_number(a)
    divisor = _coerce_number(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    return float(numerator / divisor), []
